    (73437, '50e5e380-1f89-4fa3-88de-e6ad35241316'::uuid, NULL, 'site_photo', 'g0-vlm-kind:73437', 'G0: the shorts pipeline judged image 73437 (''Tomb_of_Jahangir_Lahore_Pakistan.webp'') ''site_photo'' on ''tomb-of-jahangir''; recorded verbatim from its own selection record', '[{"source": "shorts selection record (the verdict being persisted)", "url": "video-assets/shorts/tomb-of-jahangir/selection.json", "quote": "stills[] entry with id=73437 carries verdict={\"kind\": \"site_photo\", \"people_prominent\": false, \"quality\": 5, \"relevance\": 4, \"subject\": \"ornate Mughal corridor\", \"text_or_overlay\": false}"}, {"source": "pipeline/video/shorts_select.py (the stage that produced the verdict)", "url": "pipeline/video/shorts_select.py", "quote": "VLM_MAX_SIDE caps the image sent to the vision model; the vocabulary this column copies is that stage''s own prompt output"}, {"source": "migration 0019 (the column and its CHECK constraint)", "url": "migrations/0019_wiki_images_image_kind.sql", "quote": "image_kind is nullable; NULL means no verdict was ever recorded and is NOT the same as ''unknown''. Only ''site_photo'' may be treated as clean."}, {"source": "image identity", "url": "video-assets/shorts/tomb-of-jahangir/selection.json", "quote": "entry id=73437 filename=''Tomb_of_Jahangir_Lahore_Pakistan.webp'' is_hero=False - the id is wiki_images.id, checked against production by --verify, not assumed"}, {"source": "caveat, recorded with the write rather than after it", "url": "output/remediation/gallery_design/DESIGN.md", "quote": "the vision model''s semantic competence on archaeological imagery is unverified; these rows record the pipeline''s existing verdicts and are a first reviewable batch, not a validated classifier"}]'::jsonb);

DO $$
DECLARE
    bad      integer;
    moved    integer := 0;
    expected integer := 105;
    r        RECORD;
BEGIN

    -- scope guard 1: every planned row exists
    SELECT count(*) INTO bad FROM _kind_plan p
      LEFT JOIN wiki_images w ON w.id = p.image_id WHERE w.id IS NULL;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0 image_kind: % planned row(s) do not exist', bad;
    END IF;

    -- scope guard 2: every planned row belongs to a curated site.
    -- The source name is passed as a RAISE argument, not embedded in the message: a literal
    -- 'ancient_nerds' inside a single-quoted RAISE message terminates the string and the whole
    -- statement fails to parse (measured - the rehearsal caught exactly that).
    SELECT count(*) INTO bad
      FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id
      JOIN unified_sites s ON s.id = w.site_id
     WHERE s.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0 image_kind: % planned row(s) are outside source_id %', bad, 'ancient_nerds';
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names. NULL-safe:
    -- `image_kind = NULL` is NULL, not true, and would match nothing.
    SELECT count(*) INTO bad
      FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id
     WHERE w.image_kind IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0 image_kind: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and the
    -- function raises unless exactly one row matched
    FOR r IN SELECT * FROM _kind_plan ORDER BY image_id LOOP
        moved := moved + apply_remediation_change(
            'wiki_images', 'image_kind', 'id', r.image_id::text,
            r.old_value, r.new_value,
            'G0/vlm-kind', '2026-09-21_gallery-verdicts-persist', r.change_key, 'authoritative',
            r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'G0 image_kind: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id
     WHERE w.image_kind IS DISTINCT FROM p.new_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0 image_kind: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _kind_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.image_id::text AND l.table_name = 'wiki_images'
       AND l.column_name = 'image_kind'
       AND l.run_stamp = '2026-09-21_gallery-verdicts-persist'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'G0 image_kind: % planned row(s) disagree with the journal', bad;
    END IF;

    -- invariant 3: this run stamp journalled nothing outside wiki_images.image_kind. In the
    -- transaction, before COMMIT: the mechanical lane raises here, and G0 used to print the same
    -- number among its post-commit reads - which aborts *after* the COMMIT instead of before it.
    -- Fail-closed means fail early.
    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-09-21_gallery-verdicts-persist'
       AND (l.table_name <> 'wiki_images' OR l.column_name <> 'image_kind');
    IF bad > 0 THEN
        RAISE EXCEPTION
            'G0 image_kind: this run stamp journalled % row(s) outside wiki_images.image_kind',
            bad;
    END IF;
END $$;


SELECT 'planned rows written', count(*)::text FROM wiki_images
 WHERE image_kind = 'site_photo' AND id IN (SELECT image_id FROM _kind_plan);
SELECT 'rows still NULL among planned', count(*)::text
  FROM _kind_plan p JOIN wiki_images w ON w.id = p.image_id WHERE w.image_kind IS NULL;
SELECT 'journal rows for this run', count(*)::text FROM remediation_change_log
 WHERE run_stamp = '2026-09-21_gallery-verdicts-persist';
SELECT 'journal rows for this run outside wiki_images.image_kind', count(*)::text
  FROM remediation_change_log
 WHERE run_stamp = '2026-09-21_gallery-verdicts-persist'
   AND (table_name <> 'wiki_images' OR column_name <> 'image_kind');
SELECT 'journal rows for this run with no evidence', count(*)::text
  FROM remediation_change_log
 WHERE run_stamp = '2026-09-21_gallery-verdicts-persist' AND (evidence IS NULL OR evidence = '[]'::jsonb);
SELECT 'table-wide context: rows with image_kind = site_photo (never compared to the journal)',
       count(*)::text FROM wiki_images WHERE image_kind = 'site_photo';
SELECT 'context only: curated rows still without a kind', count(*)::text
  FROM wiki_images w JOIN unified_sites s ON s.id = w.site_id
 WHERE s.source_id = 'ancient_nerds' AND w.image_kind IS NULL;
SELECT 'rows with a kind outside the vocabulary', count(*)::text FROM wiki_images
 WHERE image_kind IS NOT NULL AND image_kind NOT IN ('artifact', 'map_or_document', 'other', 'painting_or_artwork', 'people', 'site_photo', 'unknown');
SELECT 'curated images', count(*)::text
  FROM wiki_images w JOIN unified_sites s ON s.id = w.site_id
 WHERE s.source_id = 'ancient_nerds';

COMMIT;
